// Generated by tools/generate.py from design/. Do not edit; change the design files and regenerate.
// Recipes for the mechanical slice and the upgradeable multiblocks.

ServerEvents.recipes(event => {
  // Each recipe is added on its own so one bad recipe logs an error instead of stopping the rest.
  const add = (build, id) => { try { build() } catch (e) { console.error(`utechnology: recipe ${id} failed: ${e}`) } }

  // Stock recipes replaced by changed recipes (machine and hand-crafting versions)
  event.remove({ id: "gtceu:assembler/electric_motor_mv" })
  event.remove({ id: "gtceu:shaped/electric_motor_mv" })
  event.remove({ id: "gtceu:assembler/electric_motor_hv" })
  event.remove({ id: "gtceu:shaped/electric_motor_hv" })

  // Disabled stock multiblocks (decision disable-overlapping-large-multiblocks)
  event.remove({ output: "gtceu:large_wiremill" })
  event.remove({ output: "gtceu:large_assembler" })
  event.remove({ output: "gtceu:large_cutter" })

  // Changed recipes
  add(() => event.recipes.gtceu.assembler("utechnology:motor_mv")
    .itemInputs("2x gtceu:lv_electric_motor", "utechnology:mv_stator_coil", "2x gtceu:aluminium_rod", "2x gtceu:copper_single_cable")
    .itemOutputs("gtceu:mv_electric_motor")
    .duration(200).EUt(30), "utechnology:assembler/motor_mv")
  add(() => event.recipes.gtceu.assembler("utechnology:motor_hv")
    .itemInputs("3x gtceu:mv_electric_motor", "utechnology:hv_stator_coil", "2x utechnology:precision_bearing", "2x gtceu:stainless_steel_rod", "2x gtceu:silver_double_cable")
    .itemOutputs("gtceu:hv_electric_motor")
    .duration(200).EUt(120), "utechnology:assembler/motor_hv")

  // New recipes
  add(() => event.recipes.utechnology.coil_winder("utechnology:stator_coil_mv")
    .itemInputs("gtceu:magnetic_steel_rod", "4x gtceu:cupronickel_double_wire")
    .itemOutputs("utechnology:mv_stator_coil")
    .duration(200).EUt(30), "utechnology:coil_winder/stator_coil_mv")
  add(() => event.recipes.utechnology.coil_winder("utechnology:stator_coil_hv")
    .itemInputs("gtceu:magnetic_steel_rod", "4x gtceu:electrum_double_wire")
    .itemOutputs("utechnology:hv_stator_coil")
    .duration(200).EUt(120), "utechnology:coil_winder/stator_coil_hv")
  add(() => event.recipes.utechnology.bearing_press("utechnology:bearing_hv")
    .itemInputs("2x gtceu:stainless_steel_ring", "gtceu:stainless_steel_rod")
    .inputFluids(Fluid.of("gtceu:lubricant", 50))
    .itemOutputs("2x utechnology:precision_bearing")
    .duration(160).EUt(120), "utechnology:bearing_press/bearing_hv")

  // Builds: machines, cores, controllers, retrofit kits, modules
  add(() => event.recipes.gtceu.assembler("utechnology:build/coil_winder_lv")
    .itemInputs("gtceu:lv_machine_hull", "2x gtceu:lv_electric_motor", "4x gtceu:copper_single_wire", "2x #gtceu:circuits/lv")
    .itemOutputs("utechnology:lv_coil_winder")
    .duration(200).EUt(7), "utechnology:assembler/build/coil_winder_lv")
  add(() => event.recipes.gtceu.assembler("utechnology:build/coil_winder_mv")
    .itemInputs("gtceu:mv_machine_hull", "2x gtceu:mv_electric_motor", "4x gtceu:cupronickel_double_wire", "2x #gtceu:circuits/mv")
    .itemOutputs("utechnology:mv_coil_winder")
    .duration(200).EUt(30), "utechnology:assembler/build/coil_winder_mv")
  add(() => event.recipes.gtceu.assembler("utechnology:build/coil_winder_hv")
    .itemInputs("gtceu:hv_machine_hull", "2x gtceu:hv_electric_motor", "4x gtceu:electrum_double_wire", "2x #gtceu:circuits/hv")
    .itemOutputs("utechnology:hv_coil_winder")
    .duration(200).EUt(120), "utechnology:assembler/build/coil_winder_hv")
  add(() => event.recipes.gtceu.assembler("utechnology:build/bearing_press_mv")
    .itemInputs("gtceu:mv_machine_hull", "2x gtceu:mv_electric_piston", "gtceu:mv_electric_motor", "2x #gtceu:circuits/mv")
    .itemOutputs("utechnology:mv_bearing_press")
    .duration(200).EUt(30), "utechnology:assembler/build/bearing_press_mv")
  add(() => event.recipes.gtceu.assembler("utechnology:build/bearing_press_hv")
    .itemInputs("gtceu:hv_machine_hull", "2x gtceu:hv_electric_piston", "gtceu:hv_electric_motor", "2x #gtceu:circuits/hv")
    .itemOutputs("utechnology:hv_bearing_press")
    .duration(200).EUt(120), "utechnology:assembler/build/bearing_press_hv")
  add(() => event.recipes.gtceu.assembler("utechnology:build/core_component_assembler")
    .itemInputs("2x gtceu:lv_robot_arm", "2x gtceu:lv_conveyor_module", "gtceu:steel_frame")
    .itemOutputs("utechnology:assembly_arm_housing")
    .duration(200).EUt(7), "utechnology:assembler/build/core_component_assembler")
  add(() => event.recipes.gtceu.assembler("utechnology:build/controller_component_assembler")
    .itemInputs("gtceu:lv_assembler", "2x gtceu:lv_robot_arm", "2x gtceu:lv_conveyor_module", "3x #gtceu:circuits/lv")
    .itemOutputs("utechnology:component_assembler")
    .duration(200).EUt(7), "utechnology:assembler/build/controller_component_assembler")
  add(() => event.recipes.gtceu.assembler("utechnology:build/core_assembly_hall")
    .itemInputs("gtceu:lv_robot_arm", "2x gtceu:lv_electric_piston", "gtceu:steel_frame")
    .itemOutputs("utechnology:assembly_bench_unit")
    .duration(200).EUt(7), "utechnology:assembler/build/core_assembly_hall")
  add(() => event.recipes.gtceu.assembler("utechnology:build/controller_assembly_hall")
    .itemInputs("gtceu:lv_assembler", "2x gtceu:lv_robot_arm", "2x gtceu:lv_electric_piston", "3x #gtceu:circuits/lv")
    .itemOutputs("utechnology:assembly_hall")
    .duration(200).EUt(7), "utechnology:assembler/build/controller_assembly_hall")
  add(() => event.recipes.gtceu.assembler("utechnology:build/core_wire_drawing_line")
    .itemInputs("2x gtceu:lv_electric_motor", "2x gtceu:small_steel_gear", "gtceu:steel_frame")
    .itemOutputs("utechnology:drawing_die_unit")
    .duration(200).EUt(7), "utechnology:assembler/build/core_wire_drawing_line")
  add(() => event.recipes.gtceu.assembler("utechnology:build/controller_wire_drawing_line")
    .itemInputs("gtceu:lv_wiremill", "2x gtceu:lv_electric_motor", "gtceu:lv_conveyor_module", "3x #gtceu:circuits/lv")
    .itemOutputs("utechnology:wire_drawing_line")
    .duration(200).EUt(7), "utechnology:assembler/build/controller_wire_drawing_line")
  add(() => event.recipes.gtceu.assembler("utechnology:build/core_turning_line")
    .itemInputs("2x gtceu:lv_electric_motor", "gtceu:lv_electric_piston", "gtceu:steel_frame")
    .itemOutputs("utechnology:spindle_unit")
    .duration(200).EUt(7), "utechnology:assembler/build/core_turning_line")
  add(() => event.recipes.gtceu.assembler("utechnology:build/controller_turning_line")
    .itemInputs("gtceu:lv_lathe", "2x gtceu:lv_electric_motor", "gtceu:lv_electric_piston", "3x #gtceu:circuits/lv")
    .itemOutputs("utechnology:turning_line")
    .duration(200).EUt(7), "utechnology:assembler/build/controller_turning_line")
  add(() => event.recipes.gtceu.assembler("utechnology:build/retrofit_kit_steel")
    .itemInputs("24x gtceu:steel_plate", "4x gtceu:steel_frame")
    .circuit(7)
    .itemOutputs("utechnology:steel_retrofit_kit")
    .duration(200).EUt(7), "utechnology:assembler/build/retrofit_kit_steel")
  add(() => event.recipes.gtceu.assembler("utechnology:build/retrofit_kit_aluminium")
    .itemInputs("24x gtceu:aluminium_plate", "4x gtceu:aluminium_frame")
    .circuit(7)
    .itemOutputs("utechnology:aluminium_retrofit_kit")
    .duration(200).EUt(30), "utechnology:assembler/build/retrofit_kit_aluminium")
  add(() => event.recipes.gtceu.assembler("utechnology:build/retrofit_kit_stainless_steel")
    .itemInputs("24x gtceu:stainless_steel_plate", "4x gtceu:stainless_steel_frame")
    .circuit(7)
    .itemOutputs("utechnology:stainless_steel_retrofit_kit")
    .duration(200).EUt(120), "utechnology:assembler/build/retrofit_kit_stainless_steel")
  add(() => event.recipes.gtceu.assembler("utechnology:build/module_specialization_lock")
    .itemInputs("gtceu:lv_robot_arm", "2x #gtceu:circuits/lv", "4x gtceu:steel_plate")
    .itemOutputs("utechnology:specialization_lock")
    .duration(200).EUt(7), "utechnology:assembler/build/module_specialization_lock")
  add(() => event.recipes.gtceu.assembler("utechnology:build/module_efficiency_coil")
    .itemInputs("4x utechnology:mv_stator_coil", "2x #gtceu:circuits/mv", "4x gtceu:aluminium_plate")
    .itemOutputs("utechnology:efficiency_coil")
    .duration(200).EUt(30), "utechnology:assembler/build/module_efficiency_coil")
  add(() => event.recipes.gtceu.assembler("utechnology:build/module_batch_bus")
    .itemInputs("2x gtceu:hv_conveyor_module", "gtceu:hv_robot_arm", "2x #gtceu:circuits/hv", "4x gtceu:stainless_steel_plate")
    .itemOutputs("utechnology:batch_bus")
    .duration(200).EUt(120), "utechnology:assembler/build/module_batch_bus")

})
